namespace sv_51eae91248a54d648915ce8252d5b3b7.Services;

public class AppointmentService
{
    public List<string> GetDoctors()
    {
        return new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Patel",
            "Dr. Williams"
        };
    }

    public List<string> GetAvailableTimeSlots(string doctor, DateTime date)
    {
        return new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        };
    }

    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(email)] = "Account has outstanding balance";
        }

        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal)
            && string.Equals(doctor, "Dr. Smith", StringComparison.Ordinal))
        {
            errors[nameof(doctor)] = "Selected doctor does not accept self-pay patients";
        }

        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors[nameof(timeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_51eae91248a54d648915ce8252d5b3b7.Services
@using System.ComponentModel.DataAnnotations
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    <h3>Step 1: Patient Information</h3>

    <div class="mb-3">
        <label class="form-label">Patient Name</label>
        <InputText class="form-control" @bind-Value="Model.PatientName" />
        <ValidationMessage For="() => Model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email</label>
        <InputText class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
        @if (serverErrors.ContainsKey("email"))
        {
            <div class="validation-message">@serverErrors["email"]</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone</label>
        <InputText class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label">Insurance Provider</label>
        <InputSelect class="form-select" @bind-Value="Model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next
        </button>
    }

    @if (showStep2)
    {
        <h3 class="mt-4">Step 2: Appointment Details</h3>

        <div class="mb-3">
            <label class="form-label">Preferred Doctor</label>
            <InputSelect class="form-select" @bind-Value="Model.Doctor" @bind-Value:after="OnDoctorOrDateChanged">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Doctor" />
            @if (serverErrors.ContainsKey("doctor"))
            {
                <div class="validation-message">@serverErrors["doctor"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Date</label>
            <InputDate class="form-control" @bind-Value="Model.AppointmentDate" @bind-Value:after="OnDoctorOrDateChanged" />
            <ValidationMessage For="() => Model.AppointmentDate" />
        </div>

        <div class="mb-3">
            <label class="form-label">Time Slot</label>
            <InputSelect class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in availableSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
            @if (serverErrors.ContainsKey("timeSlot"))
            {
                <div class="validation-message">@serverErrors["timeSlot"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label">Reason for Visit</label>
            <InputTextArea class="form-control" @bind-Value="Model.Reason" />
            <ValidationMessage For="() => Model.Reason" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability">
            Check Availability
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!validated)">
            Book Appointment
        </button>
    }
</EditForm>

@if (booked)
{
    <div class="alert alert-success mt-3">Appointment booked successfully!</div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private bool showStep2;
    private bool validated;
    private bool booked;
    private List<string> doctors = new();
    private List<string> availableSlots = new();
    private Dictionary<string, string> serverErrors = new();

    protected override void OnInitialized()
    {
        doctors = AppointmentService.GetDoctors();
    }

    private void ProceedToStep2()
    {
        // Validate step 1 fields manually
        var context = new ValidationContext(Model);
        var results = new List<ValidationResult>();
        bool isValid = Validator.TryValidateProperty(Model.PatientName,
            new ValidationContext(Model) { MemberName = nameof(Model.PatientName) }, results);
        isValid &= Validator.TryValidateProperty(Model.Email,
            new ValidationContext(Model) { MemberName = nameof(Model.Email) }, results);
        isValid &= Validator.TryValidateProperty(Model.Phone,
            new ValidationContext(Model) { MemberName = nameof(Model.Phone) }, results);
        isValid &= Validator.TryValidateProperty(Model.InsuranceProvider,
            new ValidationContext(Model) { MemberName = nameof(Model.InsuranceProvider) }, results);

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private void OnDoctorOrDateChanged()
    {
        validated = false;
        serverErrors.Clear();
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = AppointmentService.GetAvailableTimeSlots(
                Model.Doctor, Model.AppointmentDate.Value);
        }
        else
        {
            availableSlots = new();
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        validated = false;

        var errors = await AppointmentService.ValidatePatientAsync(
            Model.Email,
            Model.InsuranceProvider,
            Model.Doctor ?? "",
            Model.TimeSlot ?? "");

        if (errors.Count == 0)
        {
            validated = true;
        }
        else
        {
            serverErrors = errors;
        }
    }

    private void HandleSubmit()
    {
        if (validated)
        {
            booked = true;
        }
    }

    public class AppointmentModel
    {
        [Required(ErrorMessage = "Patient name is required")]
        public string PatientName { get; set; } = "";

        [Required(ErrorMessage = "Email is required")]
        [EmailAddress(ErrorMessage = "Invalid email format")]
        public string Email { get; set; } = "";

        [Required(ErrorMessage = "Phone is required")]
        [Phone(ErrorMessage = "Invalid phone format")]
        public string Phone { get; set; } = "";

        [Required(ErrorMessage = "Insurance provider is required")]
        public string InsuranceProvider { get; set; } = "";

        [Required(ErrorMessage = "Doctor is required")]
        public string? Doctor { get; set; }

        [Required(ErrorMessage = "Date is required")]
        [FutureDate(ErrorMessage = "Date must be in the future")]
        public DateTime? AppointmentDate { get; set; }

        [Required(ErrorMessage = "Time slot is required")]
        public string? TimeSlot { get; set; }

        [Required(ErrorMessage = "Reason is required")]
        [MaxLength(500, ErrorMessage = "Reason cannot exceed 500 characters")]
        public string? Reason { get; set; }
    }

    public class FutureDateAttribute : ValidationAttribute
    {
        public override bool IsValid(object? value)
        {
            if (value is DateTime date)
            {
                return date.Date > DateTime.Today;
            }
            return false;
        }
    }
}

